//! Wave-eight: CoRIM/CoMID reference-value and endorsement appraisal of Arm
//! CCA tokens (platform and realm) on Veraison's published corpora.
//! Provenance of every file is in `tests/data/vendor/README.md`.
//!
//! - `cca-veraison-services/`: Veraison `services` `scheme/arm-cca/test`
//!   (`cca-good.cbor` evidence, generated by `evcli`, with its valid
//!   platform and realm CoRIMs and 18 malformed ones) and `end-to-end/input`
//!   (`e2e-*`: evidence and endorsements of Veraison's end-to-end flow).
//!   The verdicts below are the ones Veraison's own tests assert.
//! - `cca-veraison-corim/`: Veraison `corim` `profiles/cca/testcases` (the
//!   CCA endorsement-profile conformance cases) and
//!   `corim/testcases/{signed,unsigned}-good-corim.cbor`.
//! - `cca-veraison/cca-token-01.cbor`: the TF-RMM token (wave seven), whose
//!   platform key is the one Veraison's end-to-end CoRIM endorses.
//!
//! None of these tokens comes from CCA silicon: no silicon vendor publishes
//! CCA evidence or CoRIMs. The evidence is Veraison's and TF-RMM's.

use vesper_aegis::cca::{CcaToken, cca_vesper_claims};
use vesper_aegis::chain::{Curve, EcPublicKey};
use vesper_aegis::corim::{
    CCA_PLATFORM_ENDORSEMENT_PROFILE, CCA_REALM_ENDORSEMENT_PROFILE, CcaAppraisalOptions,
    CcaCorimStore, ClassId, Corim, CorimId, CryptoKey, Instance, Mkey, appraise_cca,
    appraise_cca_with_options, verify_cca_with_corim, verify_cca_with_corim_options,
};

/// Veraison's `arm-cca` scheme does not compare signer IDs, and its
/// `cca-good` corpus has signer IDs that differ from its CoRIM's.
const VERAISON: CcaAppraisalOptions = CcaAppraisalOptions {
    compare_signer_id: false,
};
use vesper_aegis::error::{AttestError, ParseError};

mod support;

const NS: u64 = 1_000_000_000;
/// 2025-06-01T00:00:00Z: inside every CoRIM validity used here
/// (e2e: 2021-12-31..2099-12-31; signed-good-corim signature validity
/// 2021-12-31..2025-12-31).
const NOW: u64 = 1_748_736_000 * NS;

fn data(path: &str) -> Vec<u8> {
    let p = format!("{}/tests/data/vendor/{path}", env!("CARGO_MANIFEST_DIR"));
    std::fs::read(&p).unwrap_or_else(|e| panic!("{p}: {e}"))
}

fn svc(name: &str) -> Vec<u8> {
    data(&format!("cca-veraison-services/{name}"))
}

fn corim(path: &str) -> Corim {
    Corim::parse_unsigned(&data(path)).unwrap_or_else(|e| panic!("{path}: {e:?}"))
}

fn store(paths: &[&str]) -> CcaCorimStore {
    let mut s = CcaCorimStore::new();
    for p in paths {
        s.add(&corim(p), NOW)
            .unwrap_or_else(|e| panic!("{p}: {e:?}"));
    }
    s
}

fn b64url(s: &str) -> Vec<u8> {
    const A: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    let mut out = Vec::new();
    let (mut acc, mut bits) = (0u32, 0);
    for c in s.bytes() {
        let v = A.iter().position(|&a| a == c).expect("base64url") as u32;
        acc = (acc << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((acc >> bits) as u8);
        }
    }
    out
}

const PLATFORM_VALID: &str = "cca-veraison-services/corim-cca-platform-valid.cbor";
const REALM_VALID: &str = "cca-veraison-services/corim-cca-realm-valid.cbor";

#[test]
fn veraison_cca_good_appraises_end_to_end() {
    let c = corim(PLATFORM_VALID);
    assert_eq!(c.profile_uri(), Some(CCA_PLATFORM_ENDORSEMENT_PROFILE));
    assert_eq!(c.comids.len(), 2);
    assert_eq!(
        c.id,
        CorimId::Text("00000000-0000-0000-cca6-0000000000001".into())
    );
    let refval = &c.comids[0].reference_values[0];
    assert_eq!(
        refval.environment.class_id,
        Some(ClassId::Bytes(vec![0; 32]))
    );
    assert_eq!(refval.measurements.len(), 7);
    assert_eq!(
        refval.measurements[0].mkey,
        Some(Mkey::Text("cca.software-component".into()))
    );
    let ak = &c.comids[1].attest_keys[0];
    assert!(matches!(&ak.environment.instance, Some(Instance::Ueid(u)) if u.len() == 33));
    assert!(matches!(ak.keys.as_slice(), [CryptoKey::PkixBase64Key(_)]));
    assert_eq!(
        corim(REALM_VALID).profile_uri(),
        Some(CCA_REALM_ENDORSEMENT_PROFILE)
    );

    let s = store(&[PLATFORM_VALID, REALM_VALID]);
    assert_eq!(
        (s.platform.len(), s.realm.len(), s.endorsements.len()),
        (1, 1, 1)
    );
    assert_eq!(s.endorsements[0].cpak.curve, Curve::P256);

    // Strictly, the signer IDs differ (the CoRIM's are 0x5378..., the
    // token's 0x0706...).
    assert!(matches!(
        verify_cca_with_corim(&svc("cca-good.cbor"), &s),
        Err(AttestError::ReferenceValueMismatch {
            what: "CCA platform software component"
        })
    ));
    let (verified, a) =
        verify_cca_with_corim_options(&svc("cca-good.cbor"), &s, &VERAISON).unwrap();
    // Veraison: platform ApprovedConfig + ApprovedRuntime, realm
    // ApprovedRuntime (TestImplementation_AppraiseClaims_*_Valid).
    assert_eq!(a.sw_components_matched, 4);
    assert!(a.config_matched);
    assert!(a.manufacturing_config_matched);
    assert_eq!(a.rotpks_matched, 1);
    assert_eq!(a.rems_constrained, [true; 4]);
    assert!(a.personalization_matched);
    let pc = &verified.token.platform_claims;
    assert_eq!(pc.sw_components[0].measurement_type.as_deref(), Some("BL"));
    assert_eq!(pc.sw_components[0].version.as_deref(), Some("3.4.2"));
    assert_eq!(pc.config.as_deref(), Some(&[1u8, 2, 3][..]));
    assert_eq!(
        pc.manufacturing_config.as_deref(),
        Some(&[0x10u8, 0x10][..])
    );
    assert_eq!(pc.tbb_rotpks[0].name, "CM");
    assert_eq!(pc.tbb_rotpks[0].index, 3);
    // The token is not Vesper evidence: the Vesper binding rejects it.
    assert!(matches!(
        cca_vesper_claims(&verified, &support::runtime()),
        Err(AttestError::BindingMismatch { .. })
    ));
}

#[test]
fn veraison_cca_good_mismatches_are_typed() {
    let token = svc("cca-good.cbor");
    // No realm CoRIM: the realm is not covered.
    let s = store(&[PLATFORM_VALID]);
    assert!(matches!(
        verify_cca_with_corim_options(&token, &s, &VERAISON),
        Err(AttestError::ReferenceValueMissing { .. })
    ));
    // No platform CoRIM: no endorsed key.
    let s = store(&[REALM_VALID]);
    assert!(matches!(
        verify_cca_with_corim_options(&token, &s, &VERAISON),
        Err(AttestError::MissingCollateral { .. })
    ));

    let good = store(&[PLATFORM_VALID, REALM_VALID]);
    let verified = verify_cca_with_corim_options(&token, &good, &VERAISON)
        .unwrap()
        .0;
    let tweak = |f: &dyn Fn(&mut CcaCorimStore)| {
        let mut s = good.clone();
        f(&mut s);
        appraise_cca_with_options(&verified, &s, &VERAISON)
    };
    #[track_caller]
    fn mismatch<T: std::fmt::Debug>(r: Result<T, AttestError>) {
        assert!(
            matches!(r, Err(AttestError::ReferenceValueMismatch { .. })),
            "{r:?}"
        )
    }
    mismatch(tweak(&|s| {
        s.platform[0].sw_components[1].digests[0].value[0] ^= 1
    }));
    // With signer IDs compared, the corrected signer ID matches.
    let mut fixed = good.clone();
    for c in &mut fixed.platform[0].sw_components {
        c.signer_id = verified.token.platform_claims.sw_components[0]
            .signer_id
            .clone();
    }
    appraise_cca(&verified, &fixed).unwrap();
    fixed.platform[0].sw_components[1].signer_id[0] ^= 1;
    mismatch(appraise_cca(&verified, &fixed));
    mismatch(tweak(&|s| {
        s.platform[0].sw_components[1].name = Some("M9".into())
    }));
    mismatch(tweak(&|s| {
        s.platform[0].sw_components[1].version = Some("9.9".into())
    }));
    // The digest algorithm the token names must be the reference's.
    mismatch(tweak(&|s| {
        s.platform[0].sw_components[1].digests[0].alg = 7
    }));
    mismatch(tweak(&|s| {
        s.platform[0].config.as_mut().unwrap().value[0] ^= 1
    }));
    mismatch(tweak(&|s| {
        s.platform[0].manufacturing_config.as_mut().unwrap().value[0] ^= 1
    }));
    mismatch(tweak(&|s| {
        s.platform[0].rotpks[0].hashes.remove(0);
    }));
    mismatch(tweak(&|s| s.platform[0].rotpks[0].index = 2));
    mismatch(tweak(&|s| s.realm[0].rems[2].as_mut().unwrap()[5] ^= 1));
    mismatch(tweak(&|s| {
        s.realm[0].personalization.as_mut().unwrap()[0] ^= 1
    }));
    assert!(matches!(
        tweak(&|s| s.platform[0].implementation_id[0] ^= 1),
        Err(AttestError::ReferenceValueMissing { .. })
    ));
    assert!(matches!(
        tweak(&|s| s.realm[0].rim[0] ^= 1),
        Err(AttestError::ReferenceValueMissing { .. })
    ));
    // Removing a constraint is fine (an endorser need not constrain REM1).
    tweak(&|s| s.realm[0].rems[1] = None).unwrap();
    // A second, matching realm reference after a mismatching one is used.
    let r = tweak(&|s| {
        let mut bad = s.realm[0].clone();
        bad.rems[0].as_mut().unwrap()[0] ^= 1;
        s.realm.insert(0, bad);
    })
    .unwrap();
    assert_eq!(r.realm_reference, 1);

    // A flipped byte in the token's platform signature or payload.
    let mut t = token.clone();
    let n = t.len();
    t[n / 3] ^= 1;
    assert!(verify_cca_with_corim_options(&t, &good, &VERAISON).is_err());
    // The endorsed key belongs to another instance.
    let mut s = good.clone();
    s.endorsements[0].instance_id[5] ^= 1;
    assert!(matches!(
        verify_cca_with_corim_options(&token, &s, &VERAISON),
        Err(AttestError::MissingCollateral { .. })
    ));
    let mut s = good.clone();
    s.endorsements[0].implementation_id.as_mut().unwrap()[0] ^= 1;
    assert!(matches!(
        verify_cca_with_corim_options(&token, &s, &VERAISON),
        Err(AttestError::CollateralMismatch { .. })
    ));
}

#[test]
fn veraison_malformed_corims_are_refused() {
    // (file, Veraison's expected failure) from `scheme/arm-cca/corim_test.go`.
    for name in [
        "platform-bad-no-class",
        "platform-bad-ta-no-instance",
        "platform-bad-ta-instance",
        "platform-bad-ta-cert",
        "platform-bad-refval-no-mkey",
        "platform-bad-refval-mkey",
        "platform-bad-refval-mkey-string",
        "platform-bad-refval-cryptokeys",
        "platform-bad-refval-no-digests",
        "platform-bad-refval-no-raw-value",
        "platform-bad-refval-instance",
        "realm-bad-instance",
        "realm-bad-no-instance",
        "realm-bad-no-rim",
        "realm-bad-no-raw-value",
        "realm-bad-no-integ-regs",
    ] {
        let path = format!("cca-veraison-services/corim-cca-{name}.cbor");
        let r = Corim::parse_unsigned(&data(&path))
            .map_err(AttestError::from)
            .and_then(|c| CcaCorimStore::new().add(&c, NOW));
        assert!(r.is_err(), "{name} was accepted");
    }
    // These two are well-formed: Veraison downgrades the platform to
    // "unsafe configuration" with them; here they fail the appraisal.
    let endorsed = store(&[PLATFORM_VALID]).endorsements;
    let verified =
        vesper_aegis::cca::verify_cca_endorsed(&svc("cca-good.cbor"), &endorsed).unwrap();
    for (name, what) in [
        (
            "platform-bad-refval-mfg-cfg",
            "CCA platform manufacturing configuration",
        ),
        ("platform-bad-refval-tbb-rotpk", "CCA TBB RoTPK"),
    ] {
        let s = store(&[
            &format!("cca-veraison-services/corim-cca-{name}.cbor"),
            REALM_VALID,
        ]);
        let r = appraise_cca_with_options(&verified, &s, &VERAISON);
        assert_eq!(
            r,
            Err(AttestError::ReferenceValueMismatch { what }),
            "{name}"
        );
    }
}

#[test]
fn veraison_corim_profile_conformance_cases() {
    // `corim/profiles/cca/testcases` (corim_test.go): valid ones validate,
    // invalid ones are refused, the profile-less one parses but is not a
    // CCA CoRIM.
    for (name, ok) in [
        ("cca-platform-valid", true),
        ("cca-realm-valid", true),
        ("cca-platform-invalid-impl-id", false),
        ("cca-platform-invalid-digests", false),
        ("cca-realm-invalid-rim-size", false),
        ("cca-realm-invalid-missing-rim", false),
    ] {
        let c = corim(&format!("cca-veraison-corim/{name}.cbor"));
        let r = CcaCorimStore::new().add(&c, NOW);
        assert_eq!(r.is_ok(), ok, "{name}: {r:?}");
    }
    let c = corim("cca-veraison-corim/no-profile.cbor");
    assert_eq!(c.profile, None);
    assert!(matches!(
        CcaCorimStore::new().add(&c, NOW),
        Err(AttestError::Collateral { .. })
    ));
    let s = store(&["cca-veraison-corim/cca-platform-valid.cbor"]);
    assert_eq!(
        s.platform[0].implementation_id,
        b"acme-implementation-id-000000001"
    );
    assert_eq!(s.platform[0].sw_components.len(), 2);
    let s = store(&["cca-veraison-corim/cca-realm-valid.cbor"]);
    assert_eq!(
        s.realm[0].personalization.as_deref(),
        Some(&b"The quick brown fox jumps over 13 lazy dogs."[..])
    );
}

#[test]
fn veraison_end_to_end_inputs() {
    // The end-to-end platform CoRIM endorses the token's platform key and
    // its software components; its realm CoRIM is for a different realm
    // (RIM 0x43..), which Veraison reports as unmatched too.
    let s = store(&[
        "cca-veraison-services/e2e-cca-endorsements.cbor",
        "cca-veraison-services/e2e-cca-realm-endorsements.cbor",
    ]);
    assert_eq!(s.platform[0].sw_components.len(), 13);
    let token = svc("e2e-cca-evidence.cbor");
    assert!(matches!(
        verify_cca_with_corim(&token, &s),
        Err(AttestError::ReferenceValueMissing {
            what: "CCA realm reference values for the RIM"
        })
    ));
    // With a realm reference for the token's own RIM (and nothing else
    // constrained) the platform appraisal passes in full.
    let verified = vesper_aegis::cca::verify_cca_endorsed(&token, &s.endorsements).unwrap();
    let mut s2 = s.clone();
    s2.realm[0].rim = verified.token.realm_claims.initial_measurement.clone();
    s2.realm[0].rems = Default::default();
    s2.realm[0].personalization = None;
    let a = appraise_cca(&verified, &s2).unwrap();
    assert_eq!(a.sw_components_matched, 13);
    assert!(a.config_matched);

    // The TF-RMM token (wave seven) carries the same implementation and
    // instance IDs and is signed by the same TF-A key: the CoRIM's
    // attestation key verifies it, and its software components (BL, M1..)
    // are not the ones this CoRIM endorses.
    let tfrmm = data("cca-veraison/cca-token-01.cbor");
    assert!(matches!(
        verify_cca_with_corim(&tfrmm, &s),
        Err(AttestError::ReferenceValueMismatch {
            what: "CCA platform software component"
        })
    ));
    let t = CcaToken::parse(&tfrmm).unwrap();
    assert_eq!(t.platform_claims.sw_components.len(), 4);
    assert_eq!(
        t.platform_claims.sw_components[0]
            .measurement_type
            .as_deref(),
        Some("BL")
    );
}

#[test]
fn signed_corim_verifies_and_tampering_fails() {
    // Veraison `corim/testcases/src/ec-p256.jwk` (public part).
    let mut sec1 = vec![4];
    sec1.extend(b64url("MKBCTNIcKUSDii11ySs3526iDZ8AiTo7Tu6KPAqv7D4"));
    sec1.extend(b64url("4Etl6SRW2YiLUrN5vfvVHuhp7x8PxltmWWlbbM4IFyM"));
    let key = EcPublicKey::from_sec1(Curve::P256, &sec1).unwrap();
    let signed = data("cca-veraison-corim/signed-good-corim.cbor");
    let c = Corim::verify_signed(&signed, &key, NOW).unwrap();
    let signer = c.signer.as_ref().unwrap();
    assert_eq!(signer.name, "ACME Ltd signing key");
    assert_eq!(signer.uri.as_deref(), Some("https://acme.example"));
    // The payload is the unsigned "good" CoRIM.
    let unsigned =
        Corim::parse_unsigned(&data("cca-veraison-corim/unsigned-good-corim.cbor")).unwrap();
    assert_eq!(c.comids, unsigned.comids);
    assert_eq!(c.id, CorimId::Text("test corim id".into()));
    // Not a CCA profile.
    assert!(CcaCorimStore::new().add(&c, NOW).is_err());
    // Outside the signature validity (ends 2025-12-31).
    assert!(matches!(
        Corim::verify_signed(&signed, &key, 1_767_225_600 * NS),
        Err(AttestError::CollateralExpired { .. })
    ));
    // Wrong key, wrong curve, flipped bytes.
    let other = support::Signer::generate(Curve::P256);
    let other = EcPublicKey::from_sec1(Curve::P256, &other.sec1()).unwrap();
    assert!(matches!(
        Corim::verify_signed(&signed, &other, NOW),
        Err(AttestError::BadSignature { .. })
    ));
    let p384 = support::Signer::generate(Curve::P384);
    let p384 = EcPublicKey::from_sec1(Curve::P384, &p384.sec1()).unwrap();
    assert!(Corim::verify_signed(&signed, &p384, NOW).is_err());
    for i in (0..signed.len()).step_by(11) {
        let mut t = signed.clone();
        t[i] ^= 0x20;
        assert!(Corim::verify_signed(&t, &key, NOW).is_err(), "byte {i}");
    }
    // An unsigned CoRIM is not a signed one, and vice versa.
    assert!(
        Corim::verify_signed(
            &data("cca-veraison-corim/unsigned-good-corim.cbor"),
            &key,
            NOW
        )
        .is_err()
    );
    assert!(Corim::parse_unsigned(&signed).is_err());
}

#[test]
fn corim_parser_rejects_malformed_input_and_never_panics() {
    assert!(matches!(
        Corim::parse_unsigned(&[0xD9, 0x01, 0xF5, 0xA0]),
        Err(ParseError::Cbor { .. })
    ));
    assert!(Corim::parse_unsigned(&[]).is_err());
    assert!(Corim::parse_unsigned(&vec![0; 300 * 1024]).is_err());
    // Trailing bytes.
    let mut t = data(PLATFORM_VALID);
    t.push(0);
    assert!(Corim::parse_unsigned(&t).is_err());

    let mut rng = support::SplitMix(0xC021);
    let samples = [
        data(PLATFORM_VALID),
        data(REALM_VALID),
        data("cca-veraison-services/e2e-cca-endorsements.cbor"),
        data("cca-veraison-corim/signed-good-corim.cbor"),
    ];
    let key = support::Signer::generate(Curve::P256);
    let key = EcPublicKey::from_sec1(Curve::P256, &key.sec1()).unwrap();
    let token = svc("cca-good.cbor");
    let good = store(&[PLATFORM_VALID, REALM_VALID]);
    let verify = |t: &[u8], s: &CcaCorimStore| verify_cca_with_corim_options(t, s, &VERAISON);
    for sample in &samples {
        for _ in 0..400 {
            let mut t = sample.clone();
            for _ in 0..1 + rng.below(3) {
                let i = rng.below(t.len() as u64) as usize;
                t[i] = rng.next() as u8;
            }
            if rng.below(4) == 0 {
                let n = rng.below(t.len() as u64) as usize;
                t.truncate(n);
            }
            if let Ok(c) = Corim::parse_unsigned(&t) {
                let mut s = good.clone();
                if s.add(&c, NOW).is_ok() {
                    let _ = verify(&token, &s);
                }
            }
            let _ = Corim::verify_signed(&t, &key, NOW);
        }
    }
    // A mutated token never appraises against the good store unless it is
    // byte-identical.
    for _ in 0..300 {
        let mut t = token.clone();
        let i = rng.below(t.len() as u64) as usize;
        let old = t[i];
        t[i] = rng.next() as u8;
        if t[i] != old {
            assert!(verify(&t, &good).is_err(), "byte {i}");
        }
    }
    verify(&token, &good).unwrap();
}
